with open(path, "r", encoding="utf-8", newline="") as f: raw = f.read()
nl = "\r\n" if "\r\n" in raw else "\n"
s = raw.replace("\r\n", "\n")
have = set(re.findall(r'^\s*"([^"]+)",$', s, re.M))
low = {h.lower() for h in have}
new = sorted({n.strip() for n in MORE if n.strip() and n.strip().lower() not in low})
if not new: sys.exit("Nothing new to add.")
tail = "];\n"
if not s.rstrip().endswith("];"): sys.exit("STOP: unexpected file format. Nothing changed.")
s = s.rstrip()[:-2] + "".join('  "%s",\n' % n for n in new) + tail
with open(path, "w", encoding="utf-8", newline="") as f: f.write(s.replace("\n", nl))
print("done: added", len(new), "names; total", len(have) + len(new))
